const input = $input.first().json;
const rawQuery = String(input.query || '').trim();
const digits = rawQuery.replace(/\D/g, '');
const normalizeText = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLocaleLowerCase('fr-FR').replace(/[^a-z0-9 ]+/g, ' ').replace(/\s+/g, ' ').trim();
let normalized_query = normalizeText(rawQuery);
let valid = true;
if (input.lookup_mode === 'siret') { valid = digits.length === 14; normalized_query = digits; }
else if (input.lookup_mode === 'siren') { valid = digits.length === 9; normalized_query = digits; }
else if (input.lookup_mode === 'bounded_text') { valid = normalized_query.length >= 3; }
else valid = false;
const cache_key = `${input.lookup_mode}:${normalized_query}`;
return [{ json: { ...input, normalized_query, cache_key, invalid_reason: valid ? null : 'G8N_SIRENE_INVALID_INPUT' } }];

const input = $input.first().json;
if (input.invalid_reason) return [{ json: { ...input, status: 'invalid_input', metrics: { ...input.metrics, error_code: input.invalid_reason } } }];
const now = new Date();
const cache = input.cache_entry;
if (cache && cache.expires_at && new Date(cache.expires_at) > now) {
  return [{ json: { ...input, status: cache.status || 'single_result', candidates: cache.candidates || [], metrics: { ...input.metrics, cache_status: 'hit', result_count: (cache.candidates || []).length } } }];
}
return [{ json: { ...input, status: 'cache_miss_or_expired', stale_cache_entry: cache || null, metrics: { ...input.metrics, cache_status: cache ? 'expired' : 'miss' }, request_contract: { credential_name: 'SIRENE API — local', timeout_ms: 15000, max_candidates: input.lookup_mode === 'bounded_text' ? 10 : 1 } } }];

const input = $input.first().json;
if (!['cache_miss_or_expired'].includes(input.status)) return [{ json: input }];
const error = input.provider_error;
if (error) {
  const codeByStatus = { 401: 'G8N_SIRENE_AUTH', 403: 'G8N_SIRENE_FORBIDDEN', 408: 'G8N_SIRENE_TIMEOUT', 429: 'G8N_SIRENE_QUOTA' };
  const errorCode = codeByStatus[error.status] || 'G8N_SIRENE_PROVIDER_ERROR';
  if (input.stale_cache_entry && ['G8N_SIRENE_QUOTA', 'G8N_SIRENE_TIMEOUT', 'G8N_SIRENE_PROVIDER_ERROR'].includes(errorCode)) {
    return [{ json: { ...input, status: 'stale', candidates: input.stale_cache_entry.candidates || [], metrics: { ...input.metrics, api_call_count: 1, error_code: errorCode, result_count: (input.stale_cache_entry.candidates || []).length } } }];
  }
  return [{ json: { ...input, status: 'provider_error', candidates: [], metrics: { ...input.metrics, api_call_count: 1, error_code: errorCode, result_count: 0 } } }];
}
const candidates = input.provider_response?.candidates || [];
const status = candidates.length === 0 ? 'zero_result' : candidates.length === 1 ? 'single_result' : 'multiple_results';
return [{ json: { ...input, status, candidates, cache_write: true, metrics: { ...input.metrics, api_call_count: 1, result_count: candidates.length, error_code: null } } }];
